/* ===== HSK 2 · Sách bài tập + Bài bổ trợ · Bài 1–4 ===== */
const AUD = f => (typeof window !== "undefined" && window.TPC_AUDIO) ? "/assets/audio/" + f : "";
const TF = ["对 (đúng)", "错 (sai)"], AF = ["A", "B", "C", "D", "E", "F"];
const tf = (q, ok, x) => ({ q, o: TF, a: ok ? 0 : 1, ...(x || {}) });
const pk = (q, l, x) => ({ q, o: AF, a: AF.indexOf(l), ...(x || {}) });
const pics = p => AF.map(k => [k, `p${p}_${k}`]);
const RAD = (chars, r1, r2, ans1) => chars.map(c => ({ q: `Chữ ${c} thuộc bộ nào?`, o: [r1, r2], a: ans1.includes(c) ? 0 : 1 }));
const W = (q, words, sample, min, max) => ({ q, write: true, words, sample, min, max });
const OD = (chips, ans) => ({ q: "Sắp xếp thành câu đúng", order: chips, ans: [].concat(ans) });
const say1 = t => [["女", t]];
const dlg = (...l) => l.map(x => [x[0], x.slice(2)]);

