HWDATA["hsk2:1:extra"] = { title: "Bài bổ trợ · Bài 1 · 九月去北京旅游最好", time: 45, shuffle: true, parts: [
  { name: "Phần 1 · Điền từ thích hợp", passage: "旅游　觉得　最　为什么　运动　一起　要　新", qs: [
    { q: "1. 你（　）不喜欢吃米饭？", o: ["为什么", "觉得", "一起", "要"], a: 0 },
    { q: "2. 我（　）十月去北京旅游最好，不冷也不热。", o: ["觉得", "要", "最", "新"], a: 0 },
    { q: "3. 下午我们（　）去踢足球吧。", o: ["一起", "为什么", "最", "觉得"], a: 0 },
    { q: "4. 我们班里，大卫的汉语（　）好。", o: ["最", "要", "新", "一起"], a: 0 },
    { q: "5. 明年我（　）去中国学习汉语。", o: ["要", "最", "觉得", "为什么"], a: 0 },
    { q: "6. 你喜欢什么（　）？——我喜欢游泳。", o: ["运动", "旅游", "新", "觉得"], a: 0 }]},
  { name: "Phần 2 · Sắp xếp thành câu", qs: [
    OD(["九月", "去北京", "旅游", "最好"], ["九月去北京旅游最好"]),
    OD(["我们", "要不要", "买几个", "新椅子"], ["我们要不要买几个新椅子"]),
    OD(["它的", "眼睛", "最", "漂亮"], ["它的眼睛最漂亮"]),
    OD(["我", "三点多", "能", "回来"], ["我三点多能回来"])]},
  { name: "Phần 3 · Hoàn thành câu với từ cho sẵn (viết thêm cho câu đủ ý)", qs: [
    W("觉得 —— 你觉得什么时候去越南旅游最好？为什么？", ["觉得"], "我觉得十二月去河内旅游最好，因为那个时候天气不冷也不热。"),
    W("最 —— 你最喜欢什么运动？", ["最"], "我最喜欢踢足球，每个星期六都和朋友一起去踢。"),
    W("要 —— 这个周末你要做什么？", ["要"], "这个周末我要去商店买几个新杯子。"),
    W("多 —— 你学汉语多长时间了？", ["多"], "我学汉语一年多了。")]},
  { name: "Phần 4 · Đọc đoạn văn, trả lời câu hỏi", passage: "我叫安娜，是美国人。我很喜欢旅游，去过很多地方。我觉得九月去北京旅游最好，九月的北京不冷也不热。北京有很多好吃的菜，我最喜欢吃北京烤鸭。我还有一只小猫，它叫花花，六个多月了，它的眼睛最漂亮。我去旅游的时候，我的中国朋友帮我照顾它。", qs: [
    { q: "1. 安娜是哪国人？", o: ["中国人", "美国人", "英国人", "越南人"], a: 1 },
    { q: "2. 安娜觉得几月去北京旅游最好？", o: ["八月", "九月", "十月", "一月"], a: 1 },
    { q: "3. 安娜最喜欢吃什么？", o: ["米饭", "面条", "北京烤鸭", "苹果"], a: 2 },
    { q: "4. 花花多大了？", o: ["六个多月", "一岁多", "六岁", "六个月前"], a: 0 }]},
  { name: "Phần 5 · Viết đoạn văn 80–100 chữ", qs: [
    W("Dùng các từ dưới đây viết đoạn văn giới thiệu nơi em muốn đi du lịch nhất.", ["旅游", "觉得", "最", "为什么", "一起"], "我很喜欢旅游。我觉得越南的会安最漂亮，所以我最想去会安旅游。为什么？因为那儿的天气很好，东西也不贵，还有很多好吃的菜。我想九月和朋友一起去，九月不冷也不热。我们要在那儿住三四天，每天去看看、吃吃。我觉得这是最好的旅游。", 80, 100)]}
]};

HWDATA["hsk2:2:extra"] = { title: "Bài bổ trợ · Bài 2 · 我每天六点起床", time: 45, shuffle: true, parts: [
  { name: "Phần 1 · Điền từ thích hợp", passage: "起床　每　早上　跑步　生病　身体　药　出院", qs: [
    { q: "1. 我（　）天早上六点起床。", o: ["每", "多", "几", "都"], a: 0 },
    { q: "2. 他（　）了，今天不能来上课。", o: ["生病", "起床", "跑步", "出院"], a: 0 },
    { q: "3. 医生说你明天能（　）了。", o: ["出院", "生病", "起床", "身体"], a: 0 },
    { q: "4. 这个（　）每天吃三次。", o: ["药", "身体", "早上", "跑步"], a: 0 },
    { q: "5. 爸爸每天早上都去（　），所以身体很好。", o: ["跑步", "生病", "出院", "药"], a: 0 },
    { q: "6. 你最近（　）怎么样？", o: ["身体", "起床", "每", "出院"], a: 0 }]},
  { name: "Phần 2 · Sắp xếp thành câu", qs: [
    OD(["我", "每天", "六点", "起床"], ["我每天六点起床"]),
    OD(["他", "生病", "已经", "三天了"], ["他生病已经三天了"]),
    OD(["医生说", "你", "要", "多休息"], ["医生说你要多休息"]),
    OD(["我们", "每天早上", "一起", "去跑步"], ["我们每天早上一起去跑步"])]},
  { name: "Phần 3 · Hoàn thành câu với từ cho sẵn", qs: [
    W("每 —— 你每天几点起床？", ["每"], "我每天早上六点半起床，七点去学校。"),
    W("已经 —— 你学汉语多长时间了？", ["已经"], "我已经学了一年多了。"),
    W("生病 —— 你最近身体怎么样？", ["生病"], "我上个星期生病了，吃了药，现在好多了。"),
    W("多 + V —— 医生说什么了？", ["多"], "医生说我要多喝水，多休息。")]},
  { name: "Phần 4 · Đọc đoạn văn, trả lời câu hỏi", passage: "我爸爸是医生，他每天都很忙。他每天早上五点半起床，起床后去公园跑步，跑一个小时。七点吃早饭，七点半去医院工作。晚上八点多回家。爸爸说，跑步对身体很好，所以他很少生病。星期六和星期天他也去医院，因为有很多病人。", qs: [
    { q: "1. 爸爸做什么工作？", o: ["老师", "医生", "司机", "服务员"], a: 1 },
    { q: "2. 爸爸每天早上几点起床？", o: ["五点", "五点半", "六点", "七点半"], a: 1 },
    { q: "3. 爸爸为什么很少生病？", o: ["他每天吃药", "他常常跑步", "他不工作", "他睡得很多"], a: 1 },
    { q: "4. 星期六爸爸做什么？", o: ["在家休息", "去医院", "去旅游", "去学校"], a: 1 }]},
  { name: "Phần 5 · Viết đoạn văn 80–100 chữ", qs: [
    W("Dùng các từ dưới đây viết đoạn văn kể một ngày của em.", ["每天", "起床", "早上", "已经", "休息"], "我每天早上六点起床。起床以后，我先去跑步，跑半个小时。七点吃早饭，七点半去学校。中午我在学校吃饭，休息一个小时。下午五点回家，晚上做作业、看书。我已经学了一年汉语了，每天晚上都学半个小时。十点我就睡觉，我觉得早睡早起身体好。", 80, 100)]}
]};

