/* ================= Khoá học ================= */
function vCourse(app) {
  const c = courseOf(S.course), L = curLesson();
  if (!canUse(S.course)) { const open = P.classes.filter(x => (x.courses || []).includes(S.course)).map(x => esc(x.name));
    app.innerHTML = `<section class="view"><div class="eyebrow">${esc(c.name)}</div><h2 style="font-size:28px;margin-bottom:18px">${esc(c.sub)}</h2><div class="card lockbox" style="padding:24px;max-width:620px"><div class="lockic">${IC.lock}</div><h3 style="font-size:20px;margin:6px 0 8px">Khoá học này chưa mở cho bạn</h3><p class="muted" style="margin-top:0">Mỗi khoá học chỉ mở cho học sinh trong lớp được cô cấp quyền${open.length ? " (" + open.join(", ") + ")" : ""}. Nhập mã lớp cô gửi để vào lớp và mở khoá học.</p>${joinForm()}</div></section>`;
    bindJoin(app); return; }
  app.innerHTML = `<section class="view" style="padding-top:8px">
        <div class="tabs" role="tablist">${TABS.map(([k, n]) => `<button role="tab" class="${S.tab === k ? "on" : ""}" data-t="${k}">${n}</button>`).join("")}</div>
        <div class="toolrow"><span class="crumb">${esc(c.name)} · <b>Bài ${L.n}</b></span><span class="muted" style="font-size:12px">Cỡ chữ</span><button class="btn sm" id="fzdn">A−</button><button class="btn sm" id="fzup">A+</button></div>
        <div class="panel" id="panel" style="--fz:${S.fz}"></div>
    </section>`;
  $$(".tabs button", app).forEach(b => b.onclick = () => { stopSpeak(); S.tab = b.dataset.t; go({}); });
  $("#fzdn").onclick = () => { S.fz = Math.max(.85, +(S.fz - .15).toFixed(2)); $("#panel").style.setProperty("--fz", S.fz); go({}); };
  $("#fzup").onclick = () => { S.fz = Math.min(1.9, +(S.fz + .15).toFixed(2)); go({}); };
  const panel = $("#panel");
  if (S.tab === "home") return tHome(panel, L, c);
  if (!L.data) { panel.innerHTML = `<div class="empty"><h3>${TABS.find(t => t[0] === S.tab)[1]} · Bài ${L.n}</h3>Khung thẻ đã sẵn sàng theo mẫu Bài 5. Nội dung bài này đang được soạn.</div>`; return; }
  ({ vocab: tVocab, flash: tFlash, vexer: tVexer, gram: tGram, gexer: tGexer, read: tRead, listen: tListen, write: tWrite, hanzi: tHanzi })[S.tab](panel, L.data);
}
function sub(name, opts, def) { const v = S.sub[name] || def; return { v, html: `<div class="seg" data-sub="${name}">${opts.map(([k, n]) => `<button class="${k === v ? "on" : ""}" data-k="${k}">${n}</button>`).join("")}</div>` }; }
function bindSub(root) { $$(".seg[data-sub]", root).forEach(sg => $$("button", sg).forEach(b => b.onclick = () => { S.sub[sg.dataset.sub] = b.dataset.k; go({}); })); }

function tHome(p, L, c) {
  const D = L.data;
  p.innerHTML = `<div class="lhome">
    <div class="lhome-top"><div class="lno">${L.n}</div>
      <div class="brandline"><span class="seal">阁</span>Thượng Phương Các</div>
      <div class="eyebrow">${esc(c.name)} · Bài ${L.n}</div>
      <div class="ltitle">${esc(L.zh)}</div>
      ${L.py ? `<div class="lpy">${esc(L.py)}</div>` : ""}
      <div class="lvi">${esc(L.vi)}</div>
    </div>
    <div class="lhome-body">
      <h2 class="ph" style="margin:0">Mục tiêu bài học</h2>
      ${D ? `<div class="objs">${D.objectives.map(o => `<div class="obj"><b>${o[0]}</b><p>${o[1]}</p></div>`).join("")}</div>
      <div class="row" style="margin-top:20px"><button class="btn pri" data-t="vocab">Bắt đầu với từ vựng</button><button class="btn" id="spk-t">${IC.sound} Nghe tên bài</button></div>`
      : `<div class="objs">${["Từ vựng", "Ngữ pháp", "Đọc – nghe", "Nói – viết"].map(o => `<div class="obj"><b>${o}</b><p class="muted">Đang soạn</p></div>`).join("")}</div>`}
    </div></div>
    ${D && D.texts && D.texts.length ? `<div class="row" style="margin:26px 0 12px"><h2 class="ph" style="margin:0">Nội dung bài khoá</h2><span class="spacer"></span><button class="btn" id="h-py">${S.sub.hpy ? "Ẩn phiên âm" : "Hiện phiên âm"}</button></div>
    <div class="htexts">${D.texts.map(t => `<div style="margin-bottom:14px"><div class="row" style="justify-content:flex-end;margin-bottom:-6px"><button class="btn sm" data-ht="${t.id}">${IC.sound} Nghe</button></div>${textHTML(t, !!S.sub.hpy)}</div>`).join("")}</div>` : ""}`;
  $$("[data-t]", p).forEach(b => b.onclick = () => go({ tab: b.dataset.t }));
  const s = $("#spk-t", p); if (s) s.onclick = () => speak(L.zh.replace(/，/g, " "));
  const hp = $("#h-py", p); if (hp) hp.onclick = () => { S.sub.hpy = !S.sub.hpy; go({}); };
  $$("[data-ht]", p).forEach(b => b.onclick = () => { const t = D.texts.find(x => x.id === +b.dataset.ht); speakSeq(t.lines.map(l => [l[0], l[1]])); });
}

/* ---------- Từ vựng ---------- */
function tVocab(p, D) {
  p.innerHTML = `<div class="row" style="margin-bottom:14px"><h2 class="ph" style="margin:0">Bảng tổng hợp từ vựng <span class="muted" style="font-size:14px;font-weight:400">· ${D.vocab.length} từ</span></h2><span class="spacer"></span>
    <button class="btn navy" id="v-all">${IC.play} Nghe tất cả</button><button class="btn" id="v-stop">Dừng</button>
    <select id="v-rate" style="width:auto">${[[.6, "Chậm"], [.85, "Vừa"], [1, "Thường"]].map(([r, n]) => `<option value="${r}" ${RATE == r ? "selected" : ""}>${n}</option>`).join("")}</select>
    <button class="btn" id="v-py">Ẩn phiên âm</button><button class="btn" id="v-vi">Ẩn nghĩa</button></div>
    <div class="tbl-wrap"><table class="vt" id="vt"><thead><tr><th>STT</th><th>Chữ Hán</th><th>Phiên âm</th><th>Nghĩa</th><th>Từ loại</th><th>Cụm từ thường gặp</th><th></th></tr></thead><tbody>
    ${D.vocab.map((v, i) => `<tr><td class="num muted">${i + 1}</td><td class="hz">${v[0]}</td><td class="py"><span>${v[1]}</span></td><td class="vi"><span>${v[2]}</span></td><td class="pos">${v[3]}</td><td class="col">${v[4]}</td><td><button class="icon-btn" data-s="${i}" aria-label="Nghe ${v[0]}">${IC.sound}</button></td></tr>`).join("")}
    ${D.proper.map((v, i) => `<tr><td class="muted" style="font-size:12px">Tên riêng</td><td class="hz">${v[0]}</td><td class="py"><span>${v[1]}</span></td><td class="vi"><span>${v[2]}</span></td><td class="pos">dt. riêng</td><td></td><td><button class="icon-btn" data-sp="${i}" aria-label="Nghe">${IC.sound}</button></td></tr>`).join("")}
    </tbody></table></div>
    <div class="card" style="margin-top:18px;padding:16px 18px"><div class="eyebrow">Mở rộng · từ cùng chữ ${D.extend.word}</div>
    <div class="row" style="margin-top:8px;gap:18px">${D.extend.list.map(x => `<span><b class="zh" style="font-size:20px;color:var(--navy-2)">${x[0]}</b> <span style="color:var(--accent)">${x[1]}</span> · ${x[2]}</span>`).join("")}</div></div>`;
  $$("[data-s]", p).forEach(b => b.onclick = () => { stopSpeak(); speak(D.vocab[b.dataset.s][0]); });
  $$("[data-sp]", p).forEach(b => b.onclick = () => { stopSpeak(); speak(D.proper[b.dataset.sp][0]); });
  $("#v-rate").onchange = e => { RATE = +e.target.value; ls.set("tpc-rate", RATE); };
  $("#v-stop").onclick = () => { stopSpeak(); $$("#vt tr").forEach(r => r.style.outline = ""); };
  $("#v-all").onclick = async () => { stopSpeak(); const rows = $$("#vt tbody tr"); for (let i = 0; i < D.vocab.length; i++) { if (!document.body.contains(rows[i])) return; rows.forEach(r => r.style.background = ""); rows[i].style.background = "var(--navy-soft)"; rows[i].scrollIntoView({ block: "nearest", behavior: "smooth" }); await speak(D.vocab[i][0]); await new Promise(r => setTimeout(r, 350)); } rows.forEach(r => r.style.background = ""); };
  $("#v-py").onclick = e => { const t = $("#vt").classList.toggle("hide-py"); e.target.textContent = t ? "Hiện phiên âm" : "Ẩn phiên âm"; };
  $("#v-vi").onclick = e => { const t = $("#vt").classList.toggle("hide-vi"); e.target.textContent = t ? "Hiện nghĩa" : "Ẩn nghĩa"; };
}

/* ---------- Flashcard ---------- */
let FC = { order: null, i: 0, key: "" };
function tFlash(p, D, key) {
  const k = key || lessonKey(); if (FC.key !== k || !FC.order) FC = { order: D.vocab.map((_, i) => i), i: 0, key: k };
  const learned = new Set(ME.learned[k] || []);
  const mode = sub("fc", [["one", "Thẻ to"], ["all", "Tất cả thẻ"]], "one");
  const card = (vi, big) => { const v = D.vocab[vi]; return `<button class="fc" data-i="${vi}" aria-label="Lật thẻ ${v[0]}"><div class="fc-in">
    <div class="fc-face front">${big ? `<span class="corner">Chạm để lật</span>` : ""}${learned.has(vi) ? `<span class="learned pill ok">Đã thuộc</span>` : ""}<div class="big">${v[0]}</div></div>
    <div class="fc-face back"><div class="fpy">${v[1]}</div><div class="fvi">${v[2]}</div><div class="fpos">${v[3]}</div></div></div></button>`; };
  if (mode.v === "one") {
    const vi = FC.order[FC.i];
    p.innerHTML = `<div class="row" style="margin-bottom:16px">${mode.html}<span class="spacer"></span><span class="prog">Đã thuộc ${learned.size}/${D.vocab.length}</span></div>
    <div class="fc-stage">${card(vi, true)}
      <div class="prog num">${FC.i + 1} / ${D.vocab.length}</div>
      <div class="row" style="justify-content:center">
        <button class="btn" id="f-prev">◀ Trước</button><button class="btn navy" id="f-flip">Lật thẻ</button><button class="btn" id="f-next">Sau ▶</button>
      </div>
      <div class="row" style="justify-content:center">
        <button class="btn" id="f-say">${IC.sound} Nghe</button><button class="btn" id="f-shuf">Xáo trộn</button>
        <button class="btn ${learned.has(vi) ? "" : "pri"}" id="f-learn">${learned.has(vi) ? "Bỏ đánh dấu" : "Đánh dấu đã thuộc"}</button>
      </div><p class="muted" style="font-size:13px">Phím tắt: ← → chuyển thẻ, phím cách để lật</p></div>`;
    const fc = $(".fc", p), flip = () => fc.classList.toggle("flip");
    fc.onclick = flip; $("#f-flip").onclick = flip;
    const mv = d => { FC.i = (FC.i + d + D.vocab.length) % D.vocab.length; tFlash(p, D, key); };
    $("#f-prev").onclick = () => mv(-1); $("#f-next").onclick = () => mv(1);
    $("#f-say").onclick = () => speak(D.vocab[vi][0]);
    $("#f-shuf").onclick = () => { FC.order = shuffle(FC.order); FC.i = 0; tFlash(p, D, key); toast("Đã xáo trộn thẻ"); };
    $("#f-learn").onclick = () => { const a = new Set(ME.learned[k] || []); a.has(vi) ? a.delete(vi) : a.add(vi); ME.learned[k] = [...a]; save(); tFlash(p, D, key); };
    document.onkeydown = e => { if ((S.view === "course" ? S.tab !== "flash" : S.vtab !== "flash") || (S.sub.fc || "one") !== "one" || /INPUT|TEXTAREA|SELECT/.test(e.target.tagName)) return; if (e.key === "ArrowRight") mv(1); else if (e.key === "ArrowLeft") mv(-1); else if (e.key === " ") { e.preventDefault(); flip(); } };
  } else {
    p.innerHTML = `<div class="row" style="margin-bottom:16px">${mode.html}<span class="spacer"></span><button class="btn" id="f-shuf">Xáo trộn</button><button class="btn navy" id="f-all">Lật tất cả</button><button class="btn" id="f-none">Úp tất cả</button></div>
      <div class="fc-grid">${FC.order.map(i => card(i, false)).join("")}</div>`;
    $$(".fc", p).forEach(f => f.onclick = () => f.classList.toggle("flip"));
    $("#f-all").onclick = () => $$(".fc", p).forEach(f => f.classList.add("flip"));
    $("#f-none").onclick = () => $$(".fc", p).forEach(f => f.classList.remove("flip"));
    $("#f-shuf").onclick = () => { FC.order = shuffle(FC.order); tFlash(p, D, key); };
  }
  bindSub(p);
}

/* ---------- Câu hỏi trắc nghiệm dùng chung ---------- */
function mcqList(root, items, ex, opt = {}) {
  if (!opt.keepOrder && !items._mixed) { items = items.map(it => { const idx = shuffle(it.o.map((_, i) => i)); return Object.assign({}, it, { o: idx.map(i => it.o[i]), a: idx.indexOf(it.a) }); }); items._mixed = true; }
  // items: {q (html), o:[...], a, zh:bool, after?:html}
  let answered = 0, right = 0;
  root.innerHTML = `<div class="qlist">${items.map((it, n) => `<div class="q" data-n="${n}"><div class="qt"><span class="qn">${n + 1}</span><div style="min-width:0">${it.q}</div></div>
    <div class="opts">${it.o.map((o, j) => `<button class="opt ${it.zh ? "zh" : ""}" data-j="${j}">${String.fromCharCode(65 + j)}. ${esc(o)}</button>`).join("")}</div>${it.after || ""}</div>`).join("")}</div>
    <div class="score" hidden><span>Kết quả</span><b class="num"></b><span class="muted"></span><span class="spacer"></span><button class="btn pri">Làm lại</button></div>`;
  $$(".q", root).forEach(q => { const it = items[+q.dataset.n]; $$(".opt", q).forEach(b => b.onclick = () => {
    const j = +b.dataset.j; $$(".opt", q).forEach(x => x.disabled = true);
    $$(".opt", q)[it.a].classList.add("ok"); if (j !== it.a) b.classList.add("bad"); else right++;
    answered++; if (opt.onAnswer) opt.onAnswer(q, it, j === it.a);
    if (answered === items.length) { const sc = $(".score", root); sc.hidden = false; $("b", sc).textContent = right + " / " + items.length; $(".muted", sc).textContent = right === items.length ? "Xuất sắc!" : right >= items.length * .7 ? "Tốt lắm, xem lại câu sai nhé." : "Ôn lại phần này rồi làm lại nhé."; record(ex, right, items.length, opt.key); }
  }); });
  $(".score .btn", root).onclick = () => opt.redo ? opt.redo() : mcqList(root, items, ex, opt);
}

/* ---------- Ôn từ vựng ---------- */
function tVexer(p, D) {
  const m = sub("vx", [["mc", "Dạng 1 · Trắc nghiệm nghĩa"], ["match", "Dạng 2 · Nối từ"], ["fill", "Dạng 3 · Điền từ"]], "mc");
  p.innerHTML = `<div style="margin-bottom:16px">${m.html}</div><div id="vx"></div>`; bindSub(p);
  const box = $("#vx", p);
  if (m.v === "mc") {
    const mk = () => shuffle(D.vocab.map((_, i) => i)).slice(0, 10).map((i, n) => {
      const v = D.vocab[i], rev = n % 3 === 2;
      const others = shuffle(D.vocab.filter((_, j) => j !== i)).slice(0, 3);
      const opts = shuffle([v, ...others]);
      return rev ? { q: `Từ nào có nghĩa “<b>${esc(v[2])}</b>”?`, o: opts.map(x => x[0]), a: opts.indexOf(v), zh: true }
        : { q: `<span class="zhq" style="font-family:var(--f-zh-d);font-size:30px;font-weight:700;color:var(--navy-2)">${v[0]}</span> <span class="muted">nghĩa là gì?</span>`, o: opts.map(x => x[2]), a: opts.indexOf(v) };
    });
    const run = () => mcqList(box, mk(), "v-mc", { redo: run }); run();
  } else if (m.v === "match") {
    let misses = 0, done = 0, sel = null;
    const pick = shuffle(D.vocab.map((_, i) => i)).slice(0, 6);
    const right = shuffle(pick);
    box.innerHTML = `<p class="muted" style="margin-top:0">Chọn một chữ Hán bên trái rồi chọn nghĩa đúng bên phải.</p>
      <div class="match"><div class="col">${pick.map(i => `<button class="zh" data-i="${i}">${D.vocab[i][0]}</button>`).join("")}</div>
      <div class="col">${right.map(i => `<button data-m="${i}">${esc(D.vocab[i][2])}</button>`).join("")}</div></div>
      <div class="score" hidden><span>Hoàn thành</span><b class="num"></b><span class="muted"></span><span class="spacer"></span><button class="btn pri">Lượt mới</button></div>`;
    $$("[data-i]", box).forEach(b => b.onclick = () => { if (b.classList.contains("done")) return; $$("[data-i]", box).forEach(x => x.classList.remove("sel")); b.classList.add("sel"); sel = b; speak(D.vocab[b.dataset.i][0]); });
    $$("[data-m]", box).forEach(b => b.onclick = () => {
      if (!sel || b.classList.contains("done")) return;
      if (b.dataset.m === sel.dataset.i) { b.classList.add("done"); sel.classList.add("done"); sel.classList.remove("sel"); sel = null; done++;
        if (done === 6) { const sc = $(".score", box); sc.hidden = false; const got = Math.max(0, 6 - misses); $("b", sc).textContent = got + " / 6"; $(".muted", sc).textContent = misses ? `Nối sai ${misses} lần` : "Không sai lần nào!"; record("v-match", got, 6); } }
      else { misses++; b.classList.remove("miss"); void b.offsetWidth; b.classList.add("miss"); }
    });
    $(".score .btn", box).onclick = () => tVexer(p, D);
  } else {
    box.innerHTML = D.fill.map((g, gi) => `<div style="margin-bottom:22px"><div class="bank">${g.bank.map(w => `<span>${w}</span>`).join("")}</div>
      <div class="qlist">${g.items.map((it, n) => `<div class="q"><div class="qt"><span class="qn">${gi * 5 + n + 1}</span><span class="zhq">${esc(it[0]).replace("___", `<select class="blank-sel" data-a="${it[1]}"><option value="">——</option>${g.bank.map(w => `<option>${w}</option>`).join("")}</select>`)}</span></div></div>`).join("")}</div></div>`).join("") +
      `<div class="row"><button class="btn pri" id="fill-ck">Kiểm tra</button><button class="btn" id="fill-re">Làm lại</button></div><div class="score" hidden><span>Kết quả</span><b class="num"></b></div>`;
    $("#fill-ck").onclick = () => { let r = 0; const ss = $$(".blank-sel", box); ss.forEach(s => { const ok = s.value === s.dataset.a; r += ok; s.classList.toggle("ok-box", ok); s.classList.toggle("bad-box", !ok); s.title = ok ? "" : "Đáp án: " + s.dataset.a; const q = s.closest(".q"); let f = $(".fb", q); if (!ok) { if (!f) { f = document.createElement("div"); f.className = "fb bad-box"; q.appendChild(f); } f.textContent = "Đáp án đúng: " + s.dataset.a; } else if (f) f.remove(); }); const sc = $(".score", box); sc.hidden = false; $("b", sc).textContent = r + " / " + ss.length; record("v-fill", r, ss.length); };
    $("#fill-re").onclick = () => tVexer(p, D);
  }
}

/* ---------- Ngữ pháp ---------- */
function tGram(p, D) {
  p.innerHTML = `<h2 class="ph">Ngữ pháp trọng tâm</h2>` + D.grammar.map((g, i) => `<article class="gcard">
    <div class="gcard-h"><span class="gn">${i + 1}</span><h3>${g.h}</h3><span class="gpy">${g.py}</span><span class="spacer"></span><span class="badge navy">${g.tag}</span></div>
    ${g.parts.map(pt => `<div class="gpart"><div class="formula">${esc(pt.f)}</div><div><div>${pt.m}</div>
      <ul class="gex">${pt.ex.map(e => `<li><button class="icon-btn" data-say="${esc(e[0])}" aria-label="Nghe">${IC.sound}</button><div><div class="zh">${esc(e[0])}</div><div class="vi">${esc(e[1])}</div></div></li>`).join("")}</ul></div></div>`).join("")}
    ${g.note ? `<p class="gnote"><b>Lưu ý:</b> ${esc(g.note)}</p>` : ""}</article>`).join("") +
    `<article class="gcard"><div class="gcard-h"><span class="gn">≈</span><h3 style="font-size:22px">${D.compare.title}</h3></div>
     <div style="padding:16px 18px"><p style="margin-top:0"><b style="color:var(--ok)">Giống nhau:</b> ${esc(D.compare.same)}</p>
     <div class="tbl-wrap"><table><thead><tr><th>Điểm khác</th><th>${D.compare.a}</th><th>${D.compare.b}</th></tr></thead><tbody>${D.compare.diff.map(r => `<tr><td><b>${r[0]}</b></td><td class="zh">${esc(r[1])}</td><td class="zh">${esc(r[2])}</td></tr>`).join("")}</tbody></table></div></div></article>`;
  $$("[data-say]", p).forEach(b => b.onclick = () => { stopSpeak(); speak(b.dataset.say); });
}

/* ---------- Ôn ngữ pháp ---------- */
function tGexer(p, D) {
  const m = sub("gx", [["mc", "Dạng 1 · Chọn đáp án đúng"], ["yt", `Dạng 2 · ${D.compare.a} hay ${D.compare.b}`], ["pos", "Dạng 3 · Chọn vị trí đúng"]], "mc");
  p.innerHTML = `<div style="margin-bottom:16px">${m.html}</div><div id="gx"></div>`; bindSub(p);
  const box = $("#gx", p);
  if (m.v === "mc") {
    const run = () => mcqList(box, shuffle(D.gmc).map(x => ({ q: `<span class="zhq">${esc(x[0]).replace("___", "<u>&emsp;&emsp;</u>")}</span>`, o: x[1], a: x[2], zh: true })), "g-mc", { redo: run }); run();
  } else if (m.v === "yt") {
    const O = [D.compare.a, D.compare.b, "Cả hai đều được"];
    box.innerHTML = `<p class="muted" style="margin-top:0">Chọn từ phù hợp điền vào chỗ trống. Nếu cả ${D.compare.a} và ${D.compare.b} đều dùng được, chọn “Cả hai đều được”.</p><div id="yt"></div>`;
    const run = () => mcqList($("#yt", box), D.gyt.map(x => ({ q: `<span class="zhq">${esc(x[0]).replace("___", "<u>&emsp;&emsp;</u>")}</span>`, o: O, a: x[1] === "both" ? 2 : O.indexOf(x[1]), zh: true })), "g-yt", { redo: run, keepOrder: true }); run();
  } else {
    let n = 0, r = 0;
    box.innerHTML = `<p class="muted" style="margin-top:0">Chọn vị trí đúng (A, B, C hoặc D) cho từ trong ô đỏ — dạng bài đọc HSK 4.</p><div class="qlist">${D.gpos.map((x, i) => `<div class="q" data-i="${i}"><div class="qt"><span class="qn">${i + 1}</span><div><span class="wordtag">${x[0]}</span><div class="pos-s">${x[1].map((t, j) => esc(t) + (j < 4 ? `<button class="slot" data-j="${j}">${"ABCD"[j]}</button>` : "")).join("")}</div></div></div></div>`).join("")}</div>
      <div class="score" hidden><span>Kết quả</span><b class="num"></b><span class="spacer"></span><button class="btn pri">Làm lại</button></div>`;
    $$(".q", box).forEach(q => { const x = D.gpos[q.dataset.i]; $$(".slot", q).forEach(b => b.onclick = () => {
      $$(".slot", q).forEach(s => s.disabled = true); const j = +b.dataset.j; $$(".slot", q)[x[2]].classList.add("ok"); if (j !== x[2]) b.classList.add("bad"); else r++;
      const full = x[1].map((t, k) => t + (k === x[2] ? (x[0] === "来说" ? "来说" : x[0]) : "")).join("");
      const f = document.createElement("div"); f.className = "fb " + (j === x[2] ? "ok-box" : "bad-box"); f.innerHTML = `<span class="zh">${esc(full)}</span>`; q.appendChild(f);
      if (++n === D.gpos.length) { const sc = $(".score", box); sc.hidden = false; $("b", sc).textContent = r + " / " + n; record("g-pos", r, n); }
    }); });
    $(".score .btn", box).onclick = () => tGexer(p, D);
  }
}

/* ---------- Luyện đọc ---------- */
function textHTML(t, showPy) {
  const body = t.lines[0][0] ? `<div class="dl">${t.lines.map(l => `<span class="who">${l[0]}：</span><span class="say">${esc(l[1])}<span class="pyl">${esc(py(l[1]))}</span></span>`).join("")}</div>`
    : `<p class="para">${esc(t.lines[0][1])}<span class="pyl" style="margin-top:6px">${esc(py(t.lines[0][1]))}</span></p>`;
  return `<div class="textbox ${showPy ? "" : "hide-py"}"><div class="row"><span class="badge">课文 ${t.id}</span><h3>${t.title}</h3></div><div class="muted" style="margin-top:4px">${t.vi}</div>${body}</div>`;
}
function tRead(p, D) {
  if (!D.texts || !D.texts.length) { p.innerHTML = `<p class="muted">Bài này chưa có bài khoá.</p>`; return; }
  let ti = +(S.sub.rt || 1); if (!D.texts.some(x => x.id === ti)) { ti = D.texts[0].id; S.sub.rt = ti; }
  const t = D.texts.find(x => x.id === ti), showPy = !!S.sub.rpy;
  p.innerHTML = `<div class="row" style="margin-bottom:14px"><div class="seg" id="rt">${D.texts.map(x => `<button class="${x.id === ti ? "on" : ""}" data-k="${x.id}">Bài khoá ${x.id}</button>`).join("")}</div><span class="spacer"></span>
    <button class="btn" id="r-py">${showPy ? "Ẩn phiên âm" : "Hiện phiên âm"}</button><button class="btn" id="r-say">${IC.sound} Nghe bài khoá</button><button class="btn ghost" id="r-stop">Dừng</button></div>
    ${textHTML(t, showPy)}<h2 class="ph">Câu hỏi đọc hiểu</h2><div id="rq"></div>`;
  $$("#rt button", p).forEach(b => b.onclick = () => { S.sub.rt = +b.dataset.k; go({}); });
  $("#r-py").onclick = () => { S.sub.rpy = !showPy; go({}); };
  $("#r-say").onclick = () => speakSeq(t.lines.map(l => [l[0], l[1]]));
  $("#r-stop").onclick = stopSpeak;
  const qs = D.read.filter(q => q[0] === ti);
  const run = () => mcqList($("#rq", p), qs.map(q => ({ q: `<span class="zhq">${esc(q[1])}</span>`, o: q[2], a: q[3], zh: true })), "read", { redo: run }); run();
}

/* ---------- Luyện nghe ---------- */
function tListen(p, D) {
  const m = sub("ls", [["q", "Nghe và chọn đáp án"], ["t", "Nghe bài khoá"]], "q");
  p.innerHTML = `<div class="row" style="margin-bottom:16px">${m.html}<span class="spacer"></span><label class="muted" style="font-size:13px">Tốc độ</label><select id="l-rate" style="width:auto">${[[.6, "Chậm"], [.85, "Vừa"], [1, "Thường"]].map(([r, n]) => `<option value="${r}" ${RATE == r ? "selected" : ""}>${n}</option>`).join("")}</select></div><div id="lx"></div>`;
  bindSub(p); $("#l-rate").onchange = e => { RATE = +e.target.value; ls.set("tpc-rate", RATE); };
  const box = $("#lx", p);
  if (!VOICES.length && "speechSynthesis" in window) box.insertAdjacentHTML("beforebegin", `<p class="fb bad-box" style="margin-top:0">Máy chưa có giọng đọc tiếng Trung, âm thanh có thể không đúng. Hãy cài giọng Chinese (Mandarin) trong cài đặt ngôn ngữ của thiết bị hoặc dùng Chrome/Safari.</p>`);
  if (m.v === "q") {
    const items = D.listen.map(x => ({ q: `<div class="row lcard" style="gap:12px"><button class="play" data-play aria-label="Phát">${IC.play}</button><span class="muted">Nghe đoạn hội thoại rồi trả lời câu hỏi (câu hỏi được đọc ở cuối)</span></div>`, o: x.o, a: x.a, zh: true, after: `<details style="margin-top:8px"><summary class="muted" style="cursor:pointer;font-size:13px">Xem lời thoại</summary><div class="trans">${x.s.map(l => `<div><b>${l[0]}：</b>${esc(l[1])}</div>`).join("")}<div><b>问：</b>${esc(x.q)}</div></div></details>`, x }));
    const run = () => { mcqList(box, items, "listen", { redo: run }); $$(".q", box).forEach(q => { const x = items[+q.dataset.n].x, b = $("[data-play]", q); b.onclick = async () => { $$(".play.on").forEach(e => e.classList.remove("on")); b.classList.add("on"); await speakSeq([...x.s, ["男", "问：" + x.q]]); b.classList.remove("on"); }; }); };
    run();
  } else {
    box.innerHTML = D.texts.map(t => `<div class="q lcard" style="margin-bottom:12px"><div class="row"><button class="play" data-t="${t.id}" aria-label="Phát bài khoá ${t.id}">${IC.play}</button><div><b class="zh" style="font-size:18px">课文 ${t.id} · ${t.title}</b><div class="muted" style="font-size:13px">${t.vi}</div></div><span class="spacer"></span><button class="btn sm" data-show="${t.id}">Hiện lời</button></div><div class="tx" hidden></div></div>`).join("");
    $$("[data-t]", box).forEach(b => b.onclick = async () => { const t = D.texts[b.dataset.t - 1]; $$(".play.on").forEach(e => e.classList.remove("on")); b.classList.add("on"); await speakSeq(t.lines); b.classList.remove("on"); });
    $$("[data-show]", box).forEach(b => b.onclick = () => { const tx = $(".tx", b.closest(".q")); tx.hidden = !tx.hidden; if (!tx.innerHTML) tx.innerHTML = textHTML(D.texts[b.dataset.show - 1], false); b.textContent = tx.hidden ? "Hiện lời" : "Ẩn lời"; });
  }
}

/* ---------- Luyện viết ---------- */
function selfGrade(q, onDone) {
  const r = document.createElement("div"); r.className = "row"; r.style.marginTop = "8px";
  r.innerHTML = `<span class="muted" style="font-size:13px">Tự đánh giá:</span><button class="btn sm" data-g="1">Đúng ý</button><button class="btn sm" data-g="0">Chưa đúng</button>`;
  q.appendChild(r); $$("button", r).forEach(b => b.onclick = () => { r.innerHTML = b.dataset.g === "1" ? `<span class="pill ok">Đúng</span>` : `<span class="pill late">Cần ôn lại</span>`; onDone(b.dataset.g === "1"); });
}
function tWrite(p, D) {
  const m = sub("wx", [["order", "Dạng 1 · Sắp xếp câu"], ["vz", "Dạng 2 · Dịch Việt → Trung"], ["zv", "Dạng 3 · Dịch Trung → Việt"], ["make", "Dạng 4 · Dùng từ đặt câu"]], "order");
  p.innerHTML = `<div style="margin-bottom:16px">${m.html}</div><div id="wx"></div>`; bindSub(p);
  const box = $("#wx", p); let n = 0, r = 0;
  const fin = (ex, total) => { if (n === total) { const sc = $(".score", box); sc.hidden = false; $("b", sc).textContent = r + " / " + total; record(ex, r, total); } };
  const scoreBar = `<div class="score" hidden><span>Kết quả</span><b class="num"></b><span class="spacer"></span><button class="btn pri" id="w-re">Làm lại</button></div>`;
  if (m.v === "order") {
    box.innerHTML = `<p class="muted" style="margin-top:0">Bấm lần lượt các từ để ghép thành câu đúng. Bấm vào từ trong khung để trả lại.</p><div class="qlist">${D.order.map((x, i) => `<div class="q" data-i="${i}"><div class="qt"><span class="qn">${i + 1}</span><span class="muted">${esc(x[2])}</span></div><div class="tiles ans"></div><div class="tiles pool">${shuffle(x[0]).map(t => `<button class="tile">${esc(t)}</button>`).join("")}</div><div class="row"><button class="btn sm pri" data-ck>Kiểm tra</button></div></div>`).join("")}</div>${scoreBar}`;
    $$(".q", box).forEach(q => { const x = D.order[q.dataset.i], ans = $(".ans", q), pool = $(".pool", q);
      q.addEventListener("click", e => { const t = e.target.closest(".tile"); if (!t || q.dataset.done) return; (t.parentElement === pool ? ans : pool).appendChild(t); });
      $("[data-ck]", q).onclick = () => { if (q.dataset.done) return; if ($$(".tile", pool).length) return toast("Hãy dùng hết các từ"); q.dataset.done = 1; const ok = norm($$(".tile", ans).map(t => t.textContent).join("")) === norm(x[1]); n++; r += ok; ans.classList.add(ok ? "ok-box" : "bad-box"); q.insertAdjacentHTML("beforeend", `<div class="ref"><span class="zh">${esc(x[1])}</span></div>`); fin("w-order", D.order.length); };
    });
  } else if (m.v === "vz") {
    box.innerHTML = `<p class="muted" style="margin-top:0">Dịch sang tiếng Trung (gõ chữ Hán). Nếu cách viết khác đáp án, xem câu mẫu và tự đánh giá.</p><div class="qlist">${D.vz.map((x, i) => `<div class="q" data-i="${i}"><div class="qt"><span class="qn">${i + 1}</span><span>${esc(x[0])}</span></div><div class="row"><input id="vz${i}" lang="zh" class="zh" style="flex:1;min-width:200px;font-size:18px" placeholder="Nhập câu tiếng Trung…"><button class="btn sm pri" data-ck>Kiểm tra</button></div></div>`).join("")}</div>${scoreBar}`;
    $$(".q", box).forEach(q => { const x = D.vz[q.dataset.i]; $("[data-ck]", q).onclick = () => { if (q.dataset.done) return; const v = norm($("input", q).value); if (!v) return toast("Hãy nhập câu trả lời"); q.dataset.done = 1;
      const ok = x[1].some(a => norm(a) === v); q.insertAdjacentHTML("beforeend", `<div class="ref">Câu mẫu: <span class="zh">${esc(x[1][0])}</span></div>`);
      if (ok) { $("input", q).classList.add("ok-box"); n++; r++; fin("w-vz", D.vz.length); } else selfGrade(q, g => { n++; r += g; fin("w-vz", D.vz.length); }); }; });
  } else if (m.v === "zv") {
    box.innerHTML = `<p class="muted" style="margin-top:0">Dịch sang tiếng Việt, sau đó xem bản dịch tham khảo và tự đánh giá.</p><div class="qlist">${D.zv.map((x, i) => `<div class="q" data-i="${i}"><div class="qt"><span class="qn">${i + 1}</span><span class="zhq">${esc(x[0])}</span><button class="icon-btn" data-say aria-label="Nghe">${IC.sound}</button></div><textarea id="zv${i}" rows="2" placeholder="Bản dịch của bạn…"></textarea><div class="row" style="margin-top:8px"><button class="btn sm pri" data-ck>Xem bản dịch tham khảo</button></div></div>`).join("")}</div>${scoreBar}`;
    $$(".q", box).forEach(q => { const x = D.zv[q.dataset.i]; $("[data-say]", q).onclick = () => speak(x[0]); $("[data-ck]", q).onclick = () => { if (q.dataset.done) return; q.dataset.done = 1; q.insertAdjacentHTML("beforeend", `<div class="ref">${esc(x[1])}</div>`); selfGrade(q, g => { n++; r += g; fin("w-zv", D.zv.length); }); }; });
  } else {
    box.innerHTML = `<p class="muted" style="margin-top:0">Dùng từ cho sẵn viết một câu hoàn chỉnh (dạng Viết phần 2 của HSK 4).</p><div class="qlist">${D.make.map((x, i) => `<div class="q" data-i="${i}"><div class="qt"><span class="qn">${i + 1}</span><span><span class="wordtag">${x[0]}</span><span class="muted">Gợi ý tình huống: ${esc(x[1])}</span></span></div><input id="mk${i}" lang="zh" class="zh" style="font-size:18px" placeholder="Viết câu có từ ${x[0]}…"><div class="row" style="margin-top:8px"><button class="btn sm pri" data-ck>Kiểm tra</button></div></div>`).join("")}</div>${scoreBar}`;
    $$(".q", box).forEach(q => { const x = D.make[q.dataset.i]; $("[data-ck]", q).onclick = () => { if (q.dataset.done) return; const v = $("input", q).value.trim();
      if (!v.includes(x[0])) return toast("Câu cần có từ " + x[0]); if (norm(v).length < 5) return toast("Câu hơi ngắn, viết đầy đủ hơn nhé");
      q.dataset.done = 1; q.insertAdjacentHTML("beforeend", `<div class="ref">Câu mẫu: <span class="zh">${esc(x[2])}</span></div>`); selfGrade(q, g => { n++; r += g; fin("w-make", D.make.length); }); }; });
  }
  const re = $("#w-re", box); if (re) re.onclick = () => tWrite(p, D);
}

