  if (X) id = await X.join(code);
  else {
    const c = P.classes.find(c => (c.code || "").toUpperCase() === code);
    if (!c) throw new Error("Mã lớp không đúng, em kiểm tra lại với cô nhé");
    if ((c.blocked || []).includes(P.uid)) throw new Error("Tài khoản này đã được cô cho rời lớp");
    id = c.id;
  }
