    const btn = f.querySelector("button"); btn.disabled = true;
    try { const id = await clsJoin(v); toast("Đã vào lớp " + clsName(id)); go({ view: "classes", cls: id }); }
    catch (er) { toast((er && er.message) || "Mã lớp không đúng"); btn.disabled = false; }
