  const dl = $("#cl-del"); dl.onclick = async () => { if (!dl.dataset.sure) { dl.dataset.sure = 1; dl.textContent = "Xoá cả lớp? Bấm lần nữa"; return; } try { await clsDelete(cur.id); toast("Đã xoá lớp"); go({ cls: null }); } catch (e) { toast("Chưa xoá được lớp"); } };
