/* ---------- Làm bài trực tiếp (sách bài tập, bổ trợ, đề luyện, đề kiểm tra) ---------- */
function vHwQuiz(app) {
  const [cid, no, id] = String(S.hq || "").replace(/^hw:/, "").split(":"), s = planOf(cid)[+no - 1], it = s && s.items.find(x => x.id === id);
  const back = () => go({ view: S.hqBack && S.hqBack !== "hwq" ? S.hqBack : "classes" });
  if (!it || !it.content) { app.innerHTML = `<section class="view"><div class="empty"><h3>Bài này chưa có nội dung</h3><button class="btn" id="hq-back">Quay lại</button></div></section>`; $("#hq-back").onclick = back; return; }
  const C = it.content, key = hwKey(s, it), prev = (ME.hwRes || {})[key], IMG = typeof HWIMG !== "undefined" ? HWIMG : {};
  const qs = []; C.parts.forEach((p, pi) => p.qs.forEach((q, qi) => { let x = { ...q, pi, qi, n: qs.length + 1 };
    if ((C.shuffle || q.mix) && x.o) { const idx = shuffle(x.o.map((_, i) => i)); x = { ...x, o: idx.map(i => q.o[i]), a: idx.indexOf(q.a) }; } qs.push(x); }));
  const auto = qs.filter(q => !q.write), essays = qs.filter(q => q.write);
  const cnt = t => [...String(t || "").replace(/[\s\p{P}a-zA-Z0-9]/gu, "")].length;
  const qHTML = q => { const p = C.parts[q.pi];
    let body;
    if (q.write) body = `${q.words ? `<div class="hq-words">${q.words.map(w => `<span class="chip" style="cursor:default">${esc(w)}</span>`).join("")}</div>` : ""}<textarea class="zh hq-w" data-n="${q.n}" rows="${q.min ? 6 : 2}" placeholder="Viết câu trả lời bằng chữ Hán…"></textarea>${q.min ? `<div class="muted hq-wc" data-n="${q.n}" style="font-size:12.5px">0 chữ · yêu cầu ${q.min}–${q.max} chữ</div>` : ""}`;
    else if (q.order) body = `<div class="hq-ord" data-n="${q.n}"><div class="hq-line zh"></div><div class="hq-chips">${shuffle(q.order.map((c, i) => i)).map(i => `<button class="chip zh" data-oi="${i}">${esc(q.order[i])}</button>`).join("")}</div><button class="btn sm ghost" data-oreset="${q.n}">Làm lại câu này</button></div>`;
    else if (q.fill) body = `<input class="zh hq-fill" data-n="${q.n}" placeholder="Nhập đáp án…" style="max-width:360px">`;
    else body = `<div class="opts">${q.o.map((o, j) => `<button class="opt zh" data-n="${q.n}" data-j="${j}">${q.o.length > 2 && !/^[A-F]$/.test(o) ? String.fromCharCode(65 + j) + ". " : ""}${esc(o)}</button>`).join("")}</div>`;
    return `<div class="q" data-n="${q.n}"><div class="qt"><span class="qn">${q.n}</span><div class="zhq" style="min-width:0;white-space:pre-line">${esc(q.q)}${q.say && !p.audio ? ` <button class="icon-btn" data-qsay="${q.n}" aria-label="Nghe">${IC.sound}</button>` : ""}</div></div>
      ${q.img && IMG[q.img] ? `<img class="hq-img" src="${IMG[q.img]}" alt="Hình câu ${q.n}">` : ""}${body}<div class="hq-fb" hidden></div></div>`; };
  const teacherView = P.teacher ? (() => { const rows = P.all.filter(m => (m.hwRes || {})[key] || ((m.hwAns || {})[key])); if (!rows.length) return `<div class="card" style="padding:16px;margin-bottom:16px"><b>Bài làm của học sinh</b><p class="muted" style="margin:6px 0 0">Chưa có học sinh nộp bài này.</p></div>`;
      return `<div class="card" style="padding:16px;margin-bottom:16px"><b>Bài làm của học sinh (${rows.length})</b>${rows.map(m => { const r = (m.hwRes || {})[key], A = (m.hwAns || {})[key] || {}; return `<details style="margin-top:8px"><summary><b>${esc(displayName(m.id, m))}</b> · ${r ? `trắc nghiệm ${r.got}/${r.total} · cao nhất ${Math.round(r.best * 100) / 10}/10` : ""}</summary>${essays.map(q => A[q.n] ? `<div style="margin:8px 0"><div class="muted" style="font-size:12.5px">Câu ${q.n}: ${esc(q.q)}</div><div class="zh hq-pass" style="margin:4px 0">${esc(A[q.n])}</div></div>` : "").join("") || `<p class="muted">Không có phần tự luận.</p>`}</details>`; }).join("")}</div>`; })() : "";
  app.innerHTML = `<section class="view hwq"><button class="btn sm ghost" id="hq-back">← Quay lại</button>
    <div class="eyebrow" style="margin-top:14px">${esc(courseOf(cid).name)} · Buổi ${s.no} · ${ITYPE[it.type] || ""}</div>
    <h2 style="font-size:26px;margin:4px 0 6px">${esc(C.title || it.label)}</h2>
    <p class="muted" style="margin-top:0">${auto.length} câu trắc nghiệm${essays.length ? ` + ${essays.length} câu tự luận (cô chấm)` : ""}${C.time ? ` · khoảng ${C.time} phút` : ""}${prev ? ` · Điểm cao nhất của em: ${Math.round(prev.best * 100) / 10}/10` : ""}. Làm hết rồi bấm <b>Nộp bài</b>.</p>
    ${teacherView}
    ${C.parts.map((p, pi) => `<div class="card hq-part" style="padding:18px;margin-bottom:16px"><h3 style="font-size:17px;margin:0 0 10px">${esc(p.name || "Phần " + (pi + 1))}</h3>
      ${p.audio ? `<audio controls preload="none" src="${esc(p.audio)}" style="width:100%;margin-bottom:8px"></audio>` : ""}
      ${p.note ? `<p class="muted" style="margin:0 0 10px;font-size:13px">${esc(p.note)}</p>` : ""}
      ${p.say ? `<button class="btn sm" data-say="${pi}" style="margin-bottom:10px">${IC.sound} Nghe đoạn hội thoại</button>` : ""}
      ${p.img && IMG[p.img] ? `<img class="hq-img wide" src="${IMG[p.img]}" alt="">` : ""}
      ${p.pics ? `<div class="hq-pics">${p.pics.map(([k, im]) => `<figure><b>${k}</b>${IMG[im] ? `<img src="${IMG[im]}" alt="Hình ${k}">` : ""}</figure>`).join("")}</div>` : ""}
      ${p.passage ? `<div class="zh hq-pass">${esc(p.passage).replace(/\n/g, "<br>")}</div>` : ""}
      <div class="qlist">${qs.filter(q => q.pi === pi).map(qHTML).join("")}</div></div>`).join("")}
    ${P.teacher ? "" : `<div class="score"><span>Đã làm <b id="hq-cnt" class="num">0</b>/${qs.length} câu</span><span class="spacer"></span><button class="btn pri" id="hq-sub">Nộp bài</button></div>`}</section>`;
  $("#hq-back").onclick = back;
  const pick = {}, built = {};
  const answered = q => q.write ? !!($(`.hq-w[data-n="${q.n}"]`, app).value || "").trim() : q.order ? (built[q.n] || []).length === q.order.length : q.fill ? !!($(`.hq-fill[data-n="${q.n}"]`, app).value || "").trim() : pick[q.n] !== undefined;
  const upd = () => { const c = $("#hq-cnt"); if (c) c.textContent = qs.filter(answered).length; };
  $$(".opt[data-j]", app).forEach(b => b.onclick = () => { if (P.teacher) return; const n = +b.dataset.n; pick[n] = +b.dataset.j; $$(`.opt[data-n="${n}"]`, app).forEach(x => x.classList.toggle("sel", x === b)); upd(); });
  $$(".hq-fill", app).forEach(i => i.oninput = upd);
  $$(".hq-w", app).forEach(t => t.oninput = () => { const q = qs[+t.dataset.n - 1], wc = $(`.hq-wc[data-n="${q.n}"]`, app); if (wc) { const c = cnt(t.value); wc.textContent = `${c} chữ · yêu cầu ${q.min}–${q.max} chữ`; wc.style.color = c >= q.min && c <= q.max + 20 ? "var(--ok)" : ""; } upd(); });
  $$(".hq-ord", app).forEach(box => { const n = +box.dataset.n, q = qs[n - 1]; built[n] = [];
    const draw = () => { $(".hq-line", box).textContent = built[n].map(i => q.order[i]).join(" ") || "Bấm các cụm từ theo thứ tự…"; $$("[data-oi]", box).forEach(b => b.disabled = built[n].includes(+b.dataset.oi)); upd(); };
    $$("[data-oi]", box).forEach(b => b.onclick = () => { if (box.dataset.locked) return; built[n].push(+b.dataset.oi); draw(); });
    $(`[data-oreset]`, box).onclick = () => { if (box.dataset.locked) return; built[n] = []; draw(); }; draw(); });
  $$("[data-say]", app).forEach(b => b.onclick = () => speakSeq(C.parts[+b.dataset.say].say));
  $$("[data-qsay]", app).forEach(b => b.onclick = () => speakSeq(qs[+b.dataset.qsay - 1].say));
  const sub = $("#hq-sub"); if (!sub) return;
  sub.onclick = () => {
    if (sub.dataset.done) { render(); window.scrollTo({ top: 0 }); return; }
    const miss = qs.length - qs.filter(answered).length;
    if (miss && !sub.dataset.sure) { sub.dataset.sure = 1; sub.textContent = `Còn ${miss} câu chưa làm — bấm lần nữa để nộp`; return; }
    let got = 0; const ans = {};
    qs.forEach(q => { const box = $(`.q[data-n="${q.n}"]`, app), fb = $(".hq-fb", box); let ok = null;
      if (q.write) { const t = $(`.hq-w[data-n="${q.n}"]`, app); ans[q.n] = t.value.trim(); t.disabled = true; fb.hidden = false; fb.innerHTML = `Câu mẫu tham khảo: <span class="zh">${esc(q.sample || "")}</span>`; return; }
      if (q.order) { const v = norm(built[q.n].map(i => q.order[i]).join("")); ok = q.ans.some(a => norm(a) === v); $(".hq-ord", box).dataset.locked = 1; $(".hq-line", box).classList.add(ok ? "ok-box" : "bad-box"); fb.hidden = false; fb.innerHTML = ok ? "" : `Đáp án: <b class="zh">${esc(q.ans[0])}</b>`; }
      else if (q.fill) { const v = norm($(`.hq-fill[data-n="${q.n}"]`, app).value || ""); ok = q.fill.some(a => norm(a) === v); $(`.hq-fill[data-n="${q.n}"]`, app).classList.add(ok ? "ok-box" : "bad-box"); fb.hidden = false; fb.innerHTML = ok ? "" : `Đáp án: <b class="zh">${esc(q.fill[0])}</b>`; }
      else { ok = pick[q.n] === q.a; $$(`.opt[data-n="${q.n}"]`, app).forEach((x, j) => { x.disabled = true; if (j === q.a) x.classList.add("ok"); else if (j === pick[q.n]) x.classList.add("bad"); }); }
      if (q.ex) { fb.hidden = false; fb.innerHTML += (fb.innerHTML ? "<br>" : "") + esc(q.ex); }
      if (ok) got++; });
    const pct = auto.length ? got / auto.length : 1;
    ME.hwRes = ME.hwRes || {}; const old = ME.hwRes[key];
    ME.hwRes[key] = { got, total: auto.length, at: Date.now(), best: Math.max(old ? old.best : 0, pct), n: (old ? old.n : 0) + 1 };
    if (essays.length) { ME.hwAns = ME.hwAns || {}; ME.hwAns[key] = ans; }
    ME.done = ME.done || {}; if (!ME.done[key]) ME.done[key] = Date.now();
    if (!ME.days.includes(today())) ME.days.push(today()); save();
    $$(".hq-fill", app).forEach(i => i.disabled = true);
    sub.dataset.done = 1; sub.textContent = "Làm lại"; sub.classList.remove("pri");
    $(".score span", app).innerHTML = `Trắc nghiệm: <b class="num">${got}/${auto.length}</b> · <b class="num">${Math.round(pct * 100) / 10}</b> điểm${essays.length ? " · phần tự luận đã gửi cô" : ""}`;
    toast("Đã nộp bài: " + got + "/" + auto.length + " câu đúng"); window.scrollTo({ top: 0, behavior: "smooth" });
  };
}

/* ================= Kỷ lục học tập ================= */
function vRecords(app) {
  const st = statsOf(ME);
  const list = (P.db ? P.all : [{ id: "me", ...ME }]).map(m => ({ id: m.id, m, s: statsOf(m) })).filter(x => x.s.points > 0 || x.id === P.uid || x.id === "me").sort((a, b) => b.s.points - a.s.points);
  const best = Object.entries(ME.scores).sort((a, b) => b[1].at - a[1].at);
  app.innerHTML = `<section class="view"><div class="eyebrow">Kỷ lục học tập</div><h2 style="font-size:28px;margin-bottom:18px">Thành tích của bạn</h2>
    <div class="stats"><div class="stat"><b>${st.points}</b><span>Điểm tích luỹ</span></div><div class="stat"><b>${st.days}</b><span>Ngày có học</span></div><div class="stat"><b>${st.done}</b><span>Bài tập đã làm</span></div><div class="stat"><b>${Math.round(st.avg * 100)}%</b><span>Điểm cao nhất trung bình</span></div><div class="stat"><b>${st.learned}</b><span>Từ đã thuộc</span></div></div>
    <div class="two">
      <div><h3 style="font-size:18px;margin-bottom:10px">Bảng xếp hạng</h3>
        ${P.db ? "" : `<p class="muted" style="font-size:13px;margin-top:0">Chế độ ngoại tuyến: chỉ hiện thành tích trên máy này.</p>`}
        <div class="tbl-wrap"><table><thead><tr><th>#</th><th>Học sinh</th><th>Lớp</th><th>Điểm</th></tr></thead><tbody>
        ${list.length ? list.map((x, i) => `<tr class="${x.id === P.uid || x.id === "me" ? "me-row" : ""}"><td><span class="rank ${i < 3 ? "r" + (i + 1) : ""}">${i + 1}</span></td><td><b>${esc(displayName(x.id === "me" ? P.uid : x.id, x.m))}</b>${x.id === P.uid || x.id === "me" ? ' <span class="badge">Bạn</span>' : ""}</td><td>${esc(x.m.cls || "—")}</td><td class="num"><b>${x.s.points}</b></td></tr>`).join("") : `<tr><td colspan="4" class="muted">Chưa có ai ghi điểm.</td></tr>`}
        </tbody></table></div>
        <p class="muted" style="font-size:12.5px">Cách tính: điểm cao nhất mỗi bài tập × 100 + 5 điểm mỗi từ đã thuộc + 20 điểm mỗi ngày có học.</p></div>
      <div><h3 style="font-size:18px;margin-bottom:10px">Điểm cao nhất từng bài tập</h3>
        ${best.length ? `<div class="tbl-wrap"><table><thead><tr><th>Bài</th><th>Dạng bài</th><th>Cao nhất</th><th>Lần làm</th></tr></thead><tbody>${best.map(([k, v]) => { const [l, ex] = k.split(":"); return `<tr><td>${esc(keyLabel(l, 1))}</td><td>${esc(EXNAMES[ex] || ex)}</td><td class="num"><span class="mini-bar"><i style="width:${v.best * 100}%"></i></span> ${Math.round(v.best * 100)}%</td><td class="num">${v.n}</td></tr>`; }).join("")}</tbody></table></div>`
        : `<div class="empty"><h3>Chưa có kỷ lục</h3>Làm một bài ôn tập ở Bài 5 để ghi điểm đầu tiên.<div style="margin-top:12px"><button class="btn pri" id="r-go">Vào Bài 5</button></div></div>`}</div>
    </div></section>`;
  const g = $("#r-go"); if (g) g.onclick = () => go({ view: "course", course: "hsk4", lesson: 5, tab: "vexer" });
}

/* ================= Giám sát học sinh ================= */
function vMonitor(app) {
  if (!P.teacher) { app.innerHTML = `<section class="view"><div class="eyebrow">Giám sát học sinh</div><h2 style="font-size:28px;margin-bottom:18px">Tiến độ cả lớp</h2><div class="empty"><h3>Mục này dành cho giáo viên</h3>${P.db ? "Bạn đang xem với tư cách học sinh. Xem tiến độ của riêng bạn ở mục Tài khoản học sinh." : "Trang đang ở chế độ ngoại tuyến. Giáo viên mở trang khi đã đăng nhập để xem tiến độ cả lớp."}</div></section>`; return; }
  const f = S.mf || { q: "", cls: "" };
  const classes = P.classes.length ? [] : [...new Set(P.all.map(m => m.cls).filter(Boolean))];
  let rows = P.all.map(m => ({ m, s: statsOf(m) }));
  if (f.cls) rows = rows.filter(x => f.cls.startsWith("c:") ? memberIds(f.cls.slice(2)).includes(x.m.id) : x.m.cls === f.cls);
  if (f.q) rows = rows.filter(x => displayName(x.m.id, x.m).toLowerCase().includes(f.q.toLowerCase()));
  rows.sort((a, b) => (b.m.lastActive || 0) - (a.m.lastActive || 0));
  const ago = t => { if (!t) return "—"; const d = (Date.now() - t) / 6e4; return d < 60 ? Math.max(1, Math.round(d)) + " phút trước" : d < 1440 ? Math.round(d / 60) + " giờ trước" : Math.round(d / 1440) + " ngày trước"; };
  const all = P.all.map(statsOf), week = P.all.filter(m => Date.now() - (m.lastActive || 0) < 7 * 864e5).length;
  app.innerHTML = `<section class="view"><div class="eyebrow">Giám sát học sinh</div><h2 style="font-size:28px;margin-bottom:18px">Tiến độ cả lớp</h2>
    <div class="stats"><div class="stat"><b>${P.all.length}</b><span>Học sinh có dữ liệu</span></div><div class="stat"><b>${week}</b><span>Hoạt động trong 7 ngày</span></div><div class="stat"><b>${all.length ? Math.round(all.reduce((s, x) => s + x.avg, 0) / all.length * 100) : 0}%</b><span>Điểm trung bình lớp</span></div><div class="stat"><b>${all.reduce((s, x) => s + x.attempts, 0)}</b><span>Lượt làm bài gần đây</span></div></div>
    <div class="row" style="margin-bottom:12px"><input id="m-q" placeholder="Tìm học sinh…" value="${esc(f.q)}" style="max-width:260px"><select id="m-cls" style="max-width:200px"><option value="">Tất cả lớp</option>${P.classes.map(x => `<option value="c:${x.id}" ${"c:" + x.id === f.cls ? "selected" : ""}>${esc(x.name)}</option>`).join("")}${classes.map(c => `<option ${c === f.cls ? "selected" : ""}>${esc(c)}</option>`).join("")}</select></div>
    ${P.all.length ? `<div class="tbl-wrap"><table><thead><tr><th>Học sinh</th>${window.TPC_WEB ? "<th>Tài khoản</th>" : ""}<th>Lớp</th><th>Đang học</th><th>Bài tập</th><th>Điểm TB</th>${Object.keys(SKILL).map(k => `<th>${k}</th>`).join("")}<th>Từ đã thuộc</th><th>Hoạt động</th></tr></thead><tbody>
      ${rows.map(({ m, s }) => `<tr><td><b>${esc(displayName(m.id, m))}</b></td>${window.TPC_WEB ? `<td class="muted" style="font-size:13px">${esc(m.email || "—")}</td>` : ""}<td>${esc(classesOf(m.id).join(", ") || m.cls || "—")}</td><td>${m.last ? esc(courseOf(m.last.course).name) + " · B" + m.last.lesson : "—"}</td><td class="num">${s.done}</td><td class="num"><b>${Math.round(s.avg * 100)}%</b></td>
        ${Object.keys(SKILL).map(k => `<td class="num">${s.skills[k] == null ? '<span class="muted">—</span>' : `<span class="mini-bar"><i style="width:${s.skills[k] * 100}%"></i></span> ${Math.round(s.skills[k] * 100)}%`}</td>`).join("")}
        <td class="num">${s.learned}</td><td class="muted" style="white-space:nowrap">${ago(m.lastActive)}</td></tr>`).join("")}</tbody></table></div>`
      : `<div class="empty"><h3>Chưa có học sinh nào ghi tiến độ</h3>${window.TPC_WEB ? "Học sinh đăng ký tài khoản ở trang đăng nhập rồi làm bài, tiến độ sẽ hiện ở đây." : ""}Chia sẻ trang cho học sinh với quyền <b>Contributor</b> (Người đóng góp) để các em lưu được điểm. Khi các em làm bài, tiến độ sẽ hiện ở đây theo thời gian thực.</div>`}
  </section>`;
  $("#m-q").oninput = e => { S.mf = { ...f, q: e.target.value }; clearTimeout(vMonitor._t); vMonitor._t = setTimeout(() => { render(); const i = $("#m-q"); i.focus(); i.setSelectionRange(i.value.length, i.value.length); }, 300); };
  $("#m-cls").onchange = e => { S.mf = { ...f, cls: e.target.value }; render(); };
}

/* ================= Tài khoản học sinh ================= */
function vAccount(app) {
  const st = statsOf(ME);
  app.innerHTML = `<section class="view"><div class="eyebrow">Tài khoản học sinh</div><h2 style="font-size:28px;margin-bottom:18px">${esc(ME.nick || P.names[P.uid] || "Hồ sơ của bạn")}</h2>
    <div class="two">
      <div class="card" style="padding:18px"><h3 style="font-size:17px;margin-bottom:12px">Thông tin học viên</h3>
        <form id="acc" class="form-grid">
          <label>Tên hiển thị<input id="ac-nick" value="${esc(ME.nick)}" placeholder="VD: Minh Anh"></label>
          <label>Lớp<input id="ac-cls" value="${esc(ME.cls)}" placeholder="VD: HSK4-K12"></label>
          <label>Mục tiêu<select id="ac-goal">${["HSK 2", "HSK 3", "HSK 4", "HSK 5", "HSK 6"].map(g => `<option ${g === ME.goal ? "selected" : ""}>${g}</option>`).join("")}</select></label>
          <div style="align-self:end"><button class="btn pri" type="submit">Lưu thông tin</button></div>
        </form>
        <p class="muted" style="font-size:13px;margin-bottom:0">${P.db && P.uid && P.canWrite !== false ? "Tiến độ được lưu vào tài khoản và cô giáo theo dõi được." : "Tài khoản này chỉ có quyền xem nên kết quả chỉ lưu trên máy này. Em bấm “Sao chép kết quả gửi cô” rồi dán vào Zalo/Messenger để gửi cô nhé."}</p>
        <div class="row" style="margin-top:12px"><button class="btn navy" id="ac-copy" type="button">Sao chép kết quả gửi cô</button></div>
        <textarea id="ac-out" rows="6" readonly hidden style="margin-top:10px;font-size:13px"></textarea>
      </div>
      <div><div class="stats" style="grid-template-columns:repeat(2,minmax(0,1fr))"><div class="stat"><b>${st.points}</b><span>Điểm tích luỹ</span></div><div class="stat"><b>${st.done}</b><span>Bài tập đã làm</span></div><div class="stat"><b>${st.learned}</b><span>Từ đã thuộc</span></div><div class="stat"><b>${st.days}</b><span>Ngày có học</span></div></div></div>
    </div>
    ${P.teacher && window.TPC_WEB ? `<div class="card guide" style="padding:18px 20px;margin-top:22px"><div class="eyebrow">Chỉ cô nhìn thấy</div><h3 style="font-size:18px;margin:4px 0 10px">Quản lý tài khoản học sinh</h3><ol style="margin:0;padding-left:20px;display:grid;gap:6px"><li>Gửi đường link website cho học sinh. Các em bấm <b>Đăng ký</b>, nhập họ tên, lớp, email và mật khẩu.</li><li>Danh sách học sinh, email và tiến độ hiện ở mục <b>Giám sát học sinh</b>.</li><li>Muốn xoá hoặc khoá tài khoản: vào Supabase → Authentication → Users.</li></ol></div>` : ""}${P.teacher && !window.TPC_WEB ? `<div class="card guide" style="padding:18px 20px;margin-top:22px"><div class="eyebrow">Chỉ cô nhìn thấy</div><h3 style="font-size:18px;margin:4px 0 10px">Cách cho học sinh vào học</h3>
      <ol style="margin:0;padding-left:20px;display:grid;gap:6px">
        <li>Mỗi học sinh tạo một tài khoản Claude miễn phí tại claude.ai bằng email của em (đây chính là tài khoản đăng nhập vào web).</li>
        <li>Cô mở trang này trên claude.ai, bấm nút <b>Chia sẻ (Share)</b> ở góc trên, nhập email từng học sinh để mời.</li>
        <li>Muốn cô theo dõi được điểm của em ở mục Giám sát: mời em với quyền <b>Người chỉnh sửa (Editor)</b> và <b>không bật</b> chia sẻ bằng đường link. Học sinh vẫn không thấy các nút giao bài, xoá bài hay giám sát.</li>
        <li>Nếu chỉ mời quyền xem hoặc gửi đường link công khai: em vẫn học được đầy đủ, nhưng kết quả chỉ lưu trên máy em; em dùng nút “Sao chép kết quả gửi cô” để gửi điểm.</li>
        <li>Mỗi em vào mục <b>Tài khoản học sinh</b>, điền tên hiển thị và lớp để cô dễ nhận ra trong bảng Giám sát.</li>
      </ol></div>` : ""}
    <h3 style="font-size:18px;margin:26px 0 10px">Lịch sử làm bài gần đây</h3>
    ${ME.attempts.length ? `<div class="tbl-wrap"><table><thead><tr><th>Thời gian</th><th>Bài</th><th>Dạng bài</th><th>Kết quả</th></tr></thead><tbody>${ME.attempts.map(a => { const [l, ex] = a.k.split(":"); return `<tr><td class="num muted">${new Date(a.at).toLocaleString("vi-VN", { hour: "2-digit", minute: "2-digit", day: "2-digit", month: "2-digit" })}</td><td>${esc(keyLabel(l))}</td><td>${esc(EXNAMES[ex] || ex)}</td><td class="num"><b>${a.got}/${a.total}</b></td></tr>`; }).join("")}</tbody></table></div>`
      : `<div class="empty"><h3>Chưa có lượt làm bài</h3>Kết quả các bài ôn tập sẽ được ghi lại ở đây.</div>`}
  </section>`;
  $("#ac-copy").onclick = async () => {
    const lines = ["Thượng Phương Các – kết quả ôn tập", "Học sinh: " + (ME.nick || "(chưa đặt tên)") + (ME.cls ? " · Lớp " + ME.cls : ""), "Ngày gửi: " + new Date().toLocaleDateString("vi-VN"), "Điểm tích luỹ: " + st.points + " · Bài tập đã làm: " + st.done + " · Từ đã thuộc: " + st.learned, ""];
    Object.entries(ME.scores).sort((x, y) => y[1].at - x[1].at).forEach(([k, v]) => { const [l, ex] = k.split(":"); lines.push("- " + keyLabel(l) + " · " + (EXNAMES[ex] || ex) + ": cao nhất " + Math.round(v.best * 100) + "% (lần gần nhất " + v.got + "/" + v.total + ")"); });
    const txt = lines.join("\n"), out = $("#ac-out"); out.value = txt; out.hidden = false;
    try { await navigator.clipboard.writeText(txt); toast("Đã sao chép, dán vào tin nhắn gửi cô nhé"); } catch (e) { out.focus(); out.select(); toast("Hãy bôi đen đoạn bên dưới và sao chép"); }
  };
  $("#acc").onsubmit = e => { e.preventDefault(); ME.nick = $("#ac-nick").value.trim().slice(0, 40); ME.cls = $("#ac-cls").value.trim().slice(0, 30); ME.goal = $("#ac-goal").value; save(); toast("Đã lưu thông tin"); render(); };
}

/* ================= Khởi động ================= */
render();
initCaps();
